  "properties": {
    "title": {
      "type": "string",
      "description": "Document title as printed"
    },
    "carrier": {
      "type": "string",
      "description": "Carrier whose logo appears on the invoice"
    },
    "documentNumber": {
      "type": "string",
      "description": "Unique identifier for the invoice"
    },
    "clientNumber": {
      "type": "string",
      "description": "Unique identifier for the client"
    },
    "issueDate": {
      "type": "string",
      "description": "Date the invoice was issued"
    },
    "page": {
      "type": "string",
      "description": "Page indicator as printed in the header block"
    },
    "shipments": {
      "type": "array",
      "description": "Every shipment row printed in the table, in page order",
      "items": {
        "type": "object",
        "required": [
          "shipmentNumber"
        ],
        "properties": {
          "shipmentNumber": {
            "type": "string"
          },
          "referenceNumber": {
            "type": [
              "string",
              "null"
            ],
            "description": "Sender / reference number, null when the cell is blank"
          },
          "date": {
            "type": "string"
          },
          "sender": {
            "type": "object",
            "properties": {
              "company": {
                "type": "string"
              },
              "address": {
                "type": "string"
              },
              "city": {
                "type": "string"
              },
              "zipCode": {
                "type": "string"
              }
            }
          },
          "recipient": {
            "type": "object",
            "properties": {
              "company": {
                "type": "string"
              },
              "address": {
                "type": "string"
              },
              "city": {
                "type": "string"
              },
              "zipCode": {
                "type": "string"
              }
            }
          },
          "typeOfService": {
            "type": "string"
          },
          "weightInKg": {
            "type": "number"
          },
          "numberOfShipments": {
            "type": "number"
          },
          "baseCharge": {
            "type": "number"
          },
          "additionalCharges": {
            "type": "array",
            "items": {
              "type": "object",
              "required": [
                "description"
              ],
              "properties": {
                "description": {
                  "type": "string"
                },
                "amount": {
                  "type": "number"
                },
                "vat": {
                  "type": "number",
                  "description": "Value from the VAT / Code column"
                },
                "grossValue": {
                  "type": "number"
                }
              }
            }
          }
        }
      }
    },
    "mostRecentShipment": {
      "type": "object",
      "required": [
        "shipmentNumber"
      ],
      "description": "Shipment with the most recent date (closest to today's date), always the last item in the list",
      "properties": {
        "sender": {
          "type": "object",
          "required": [
            "company"
          ],
          "properties": {
            "city": {
              "type": "string",
              "description": "City of the sender as it appears, excluding zip code"
            },
            "address": {
              "type": "string",
              "description": "Street address of the sender as it appears, only including number and street"
            },
            "company": {
              "type": "string",
              "description": "Sender's company name as it appears"
            },
            "zipCode": {
              "type": "string",
              "description": "Zip code of the sender as it appears"
            }
          }
        },
        "recipient": {
          "type": "object",
          "required": [
            "company"
          ],
          "properties": {
            "address": {
              "type": "string",
              "description": "Street address of the recipient as it appears, only including number and street"
            },
            "company": {
              "type": "string",
              "description": "Recipient's company name as it appears"
            }
          }
        },
        "weightInKg": {
          "type": "number",
          "description": "Weight of the shipment in kilograms"
        },
        "shipmentNumber": {
          "type": "string",
          "description": "Unique identifier for the shipment"
        },
        "referenceNumber": {
          "type": "string",
          "description": "Reference number for the shipment, must return null if not provided"
        },
        "additionalCharges": {
          "type": "array",
          "description": "Details of additional charges applied to the shipment",
          "items": {
            "type": "object",
            "required": [
              "description"
            ],
            "properties": {
              "amount": {
                "type": "number",
                "description": "Amount of the additional charge"
              },
              "description": {
                "type": "string",
                "description": "Description of the additional charge as it appears"
              }
            }
          }
        }
      }
    }
  }
}

